// Builds the Dialogflow ES agent for the Baymax voice coach (report Module 6, FR-2).
//
//   node tools/build_dialogflow_agent.js
//
// Writes backend/dialogflow/agent/ (the agent's export format) and
// backend/dialogflow/baymax-coach-agent.zip, which can be imported in the
// Dialogflow ES console (Agent settings → Export and Import → Restore from zip)
// or with the API's `agent:restore`.
//
// Intent names match the app's CoachIntent values exactly
// (app/lib/services/voice/intent_service.dart); the app maps them back by
// name. Replies are generated by the app from live workout data, so the
// intents carry no text responses of their own.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const zlib = require('zlib');

const root = path.join(__dirname, '..', 'dialogflow');
const out = path.join(root, 'agent');
const exercisesFile = path.join(__dirname, '..', '..', 'app', 'assets', 'data', 'exercises.json');

// Deterministic ids so rebuilding does not churn the files.
const id = (seed) => {
  const h = crypto.createHash('md5').update(seed).digest('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`;
};

// {exercise} marks where an exercise name goes; {topic:x} a topic word.
const intents = {
  painOrSymptom: ['my knee hurts', 'I feel pain in my back', 'my shoulder is hurting', 'I feel dizzy',
    'I feel faint', 'I have chest pain', 'I cannot breathe properly', 'I think I pulled a muscle',
    'sharp pain in my knee', 'I feel sick', 'I feel lightheaded', 'my wrist hurts'],
  confirmYes: ['yes', 'yeah', 'yes end it', 'sure', 'okay', 'confirm', 'do it', 'yes please'],
  confirmNo: ['no', 'nope', 'no keep going', 'cancel', 'never mind', 'do not', 'not now'],
  stopSession: ['stop the session', 'end session', 'end the workout', 'finish my workout', 'I am done',
    'stop the exercise', 'quit the session', 'finish this set'],
  pauseSession: ['pause', 'pause workout', 'pause the session', 'take a break', 'hold on',
    'give me a minute', 'pause it'],
  resumeSession: ['resume', 'resume workout', 'continue', 'keep going', 'carry on', 'I am ready',
    'start again', 'unpause'],
  repCount: ['how many reps have I done', 'how many reps', 'rep count', 'how many did I do',
    'how many are left', 'how many more', 'count my reps', 'how many repetitions so far',
    'how many {exercise} have I done', 'how many {exercise} did I complete so far',
    'how many {exercise} are left', 'what is my rep count', 'how many have I completed', 'number of reps so far'],
  postureScore: ['what is my score', 'what is my posture score', 'how accurate am I', 'my accuracy',
    'what is my rating', 'show my score'],
  postureFeedback: ['how is my form', 'check my form', 'am I doing it right', 'what am I doing wrong',
    'what is wrong with my posture', 'is my back straight', 'how is my posture', 'any feedback',
    'correct my form', 'are my knees okay'],
  sessionTime: ['how long have I been going', 'how long has this session been', 'elapsed time',
    'workout time', 'how much time has passed', 'session duration'],
  nextExercise: ['what is next', 'what is the next exercise', 'what comes after this', 'up next',
    'what do I do after this'],
  schedule: ['what is my workout today', 'what is on my schedule', 'show exercises', 'what is my plan today',
    'today routine', 'what exercises do I have today', 'my workout plan'],
  exerciseTechnique: ['how do I do a {exercise}', 'how to do {exercise}', 'show me how to do {exercise}',
    'teach me {exercise}', 'explain the {exercise}', 'technique for {exercise}', 'tips for {exercise}',
    'how do I do this', 'show me how', 'what are the steps', 'form tips', 'instructions please',
    '{exercise}'],
  currentExercise: ['what exercise is this', 'which exercise am I doing', 'what am I doing now',
    'what is my target', 'how many sets', 'what muscles does this work', 'current exercise'],
  startWorkout: ['start workout', 'start my workout', 'let us go', 'begin the workout', 'start exercising'],
  generalGuidance: ['how should I {topic:breathe}', 'when do I {topic:breathe} in', 'how long should I {topic:rest}',
    'how much {topic:rest} between sets', 'should I {topic:warm up}', 'do I need to {topic:stretch}',
    'should I drink {topic:water}', 'how do I stay {topic:hydrated}', 'I am {topic:tired}',
    'I want to {topic:give up}', 'this is {topic:too hard}', 'I need {topic:motivation}'],
  help: ['help', 'what can you do', 'what can I ask', 'what commands are there', 'how do you work'],
  greeting: ['hi', 'hello', 'hey baymax', 'good morning', 'good evening', 'salam'],
};

// Entity values are the app's topic ids (CoachResponder._generalTip).
const topicValues = {
  breathing: ['breathe', 'breathing', 'inhale', 'exhale', 'breath'],
  rest: ['rest', 'recover', 'recovery', 'sore'],
  warmup: ['warm up', 'warmup', 'cool down', 'stretch', 'stretching'],
  hydration: ['water', 'hydrated', 'hydration', 'drink'],
  motivation: ['tired', 'exhausted', 'give up', 'too hard', 'motivation', 'struggling'],
};

const exampleExercises = ['squat', 'push-up', 'plank', 'lunges', 'glute bridge', 'burpees', 'chair squat'];

// Entity values are the app's exercise ids, so the app can look them up directly.
function exerciseEntries() {
  const list = JSON.parse(fs.readFileSync(exercisesFile, 'utf8'));
  return list
    .filter((e) => e.id !== 'warmup' && e.id !== 'cooldown')
    .map((e) => {
      const synonyms = new Set();
      for (const n of e.name.split(/[()]/).map((s) => s.trim()).filter(Boolean)) {
        const lower = n.toLowerCase();
        for (const v of [lower, lower.replace(/-/g, ' '), lower.replace(/s$/, ''), lower.replace(/^bodyweight /, '')]) {
          if (v) synonyms.add(v);
        }
      }
      return { value: e.id, synonyms: [...synonyms] };
    });
}

function phraseParts(template, index) {
  const parts = [];
  const re = /\{(exercise|topic:[^}]+)\}/g;
  let last = 0;
  let m;
  while ((m = re.exec(template))) {
    if (m.index > last) parts.push({ text: template.slice(last, m.index), userDefined: false });
    if (m[1] === 'exercise') {
      parts.push({ text: exampleExercises[index % exampleExercises.length], alias: 'exercise', meta: '@exercise', userDefined: true });
    } else {
      parts.push({ text: m[1].slice(6), alias: 'topic', meta: '@topic', userDefined: true });
    }
    last = re.lastIndex;
  }
  if (last < template.length) parts.push({ text: template.slice(last), userDefined: false });
  return parts;
}

function param(name, dataType, intent) {
  return {
    id: id(`param:${intent}:${name}`),
    required: false,
    dataType,
    name,
    value: `$${name}`,
    promptMessages: [],
    noMatchPromptMessages: [],
    noInputPromptMessages: [],
    outputDialogContexts: [],
    isList: false,
  };
}

function intentFile(name, { exercise = false, topic = false, fallback = false } = {}) {
  return {
    id: id(`intent:${name}`),
    name,
    auto: true,
    contexts: [],
    responses: [{
      resetContexts: false,
      action: fallback ? 'input.unknown' : name,
      affectedContexts: [],
      parameters: [
        ...(exercise ? [param('exercise', '@exercise', name)] : []),
        ...(topic ? [param('topic', '@topic', name)] : []),
      ],
      messages: [],
      speech: [],
    }],
    priority: 500000,
    webhookUsed: false,
    webhookForSlotFilling: false,
    fallbackIntent: fallback,
    events: [],
    conditionalResponses: [],
    condition: '',
    conditionalFollowupEvents: [],
  };
}

function write(file, data) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(data, null, 2) + '\n');
}

fs.rmSync(out, { recursive: true, force: true });

write(path.join(out, 'package.json'), { version: '1.0.0' });
write(path.join(out, 'agent.json'), {
  description: 'Baymax micro-coaching voice assistant: workout questions and session controls.',
  language: 'en',
  shortDescription: '',
  examples: '',
  linkToDocs: '',
  displayName: 'baymax-coach',
  disableInteractionLogs: true,
  disableStackdriverLogs: true,
  defaultTimezone: 'Asia/Karachi',
  isPrivate: true,
  mlMinConfidence: 0.4,
  supportedLanguages: [],
  enableOnePlatformApi: true,
  onePlatformApiVersion: 'v2',
  analyzeQueryTextSentiment: false,
  enabledKnowledgeBaseNames: [],
  knowledgeServiceConfidenceAdjustment: 0.0,
  dialogBuilderMode: false,
  baseActionPackagesUrl: '',
  enableSpellCorrection: true,
});

for (const name of ['exercise', 'topic']) {
  write(path.join(out, 'entities', `${name}.json`), {
    id: id(`entity:${name}`), name, isOverridable: true, isEnum: false, isRegexp: false,
    automatedExpansion: false, allowFuzzyExtraction: true,
  });
}
write(path.join(out, 'entities', 'exercise_entries_en.json'), exerciseEntries());
write(path.join(out, 'entities', 'topic_entries_en.json'),
  Object.entries(topicValues).map(([value, synonyms]) => ({ value, synonyms })));

for (const [name, phrases] of Object.entries(intents)) {
  write(path.join(out, 'intents', `${name}.json`), intentFile(name, {
    exercise: phrases.some((p) => p.includes('{exercise}')),
    topic: phrases.some((p) => p.includes('{topic:')),
  }));
  write(path.join(out, 'intents', `${name}_usersays_en.json`), phrases.map((p, i) => ({
    id: id(`phrase:${name}:${p}`),
    data: phraseParts(p, i),
    isTemplate: false,
    count: 0,
    lang: 'en',
    updated: 0,
  })));
}
write(path.join(out, 'intents', 'Default Fallback Intent.json'), intentFile('Default Fallback Intent', { fallback: true }));

const zip = path.join(root, 'baymax-coach-agent.zip');
fs.writeFileSync(zip, zipDirectory(out));
console.log(`Agent written to ${out} and ${zip}`);
console.log(`${Object.keys(intents).length} intents, ${exerciseEntries().length} exercises`);

// Minimal zip writer (stored, no compression). Dialogflow needs entry names
// with forward slashes ("intents/x.json"); Windows PowerShell's
// Compress-Archive writes backslashes, which Dialogflow rejects.
function zipDirectory(dir) {
  const files = [];
  (function walk(rel) {
    for (const name of fs.readdirSync(path.join(dir, rel)).sort()) {
      const r = rel ? `${rel}/${name}` : name;
      if (fs.statSync(path.join(dir, r)).isDirectory()) walk(r);
      else files.push(r);
    }
  })('');

  const local = [];
  const central = [];
  let offset = 0;
  for (const name of files) {
    const data = fs.readFileSync(path.join(dir, name));
    const nameBuf = Buffer.from(name, 'utf8');
    const crc = zlib.crc32(data);
    const header = Buffer.alloc(30);
    header.writeUInt32LE(0x04034b50, 0);
    header.writeUInt16LE(20, 4); // version needed
    header.writeUInt16LE(0x0800, 6); // UTF-8 names
    header.writeUInt16LE(0, 8); // stored
    header.writeUInt32LE(0, 10); // time/date
    header.writeUInt32LE(crc, 14);
    header.writeUInt32LE(data.length, 18);
    header.writeUInt32LE(data.length, 22);
    header.writeUInt16LE(nameBuf.length, 26);
    header.writeUInt16LE(0, 28);
    local.push(header, nameBuf, data);

    const entry = Buffer.alloc(46);
    entry.writeUInt32LE(0x02014b50, 0);
    entry.writeUInt16LE(20, 4);
    entry.writeUInt16LE(20, 6);
    entry.writeUInt16LE(0x0800, 8);
    entry.writeUInt16LE(0, 10);
    entry.writeUInt32LE(0, 12);
    entry.writeUInt32LE(crc, 16);
    entry.writeUInt32LE(data.length, 20);
    entry.writeUInt32LE(data.length, 24);
    entry.writeUInt16LE(nameBuf.length, 28);
    entry.writeUInt32LE(offset, 42);
    central.push(entry, nameBuf);
    offset += header.length + nameBuf.length + data.length;
  }
  const centralBuf = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralBuf.length, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...local, centralBuf, end]);
}
